INSERT INTO points_of_interest (name, type, ecosystem_type, commune, description, stem_areas, heritage_type, threats, location) VALUES
('Estero Los Boldos', 'hydrological', 'fluvial', 'Cunco', 'Estero que atraviesa la zona urbana de Cunco. Hábitat de anfibios nativos y vegetación ribereña.', ARRAY['biologia','quimica','ecologia'], 'natural', ARRAY['contaminacion_domestica','canalizacion'], ST_SetSRID(ST_MakePoint(-72.023, -38.928), 4326)),
('Bosque de Roble-Raulí Cunco', 'natural', 'bosque_nativo', 'Cunco', 'Remanente de bosque nativo de roble y raulí en la periferia de Cunco. Refugio de fauna silvestre.', ARRAY['biologia','ecologia','matematica'], 'natural', ARRAY['expansion_urbana','tala'], ST_SetSRID(ST_MakePoint(-72.032, -38.923), 4326)),
('Rewe Comunitario Cunco', 'cultural', 'cultural_mapuche', 'Cunco', 'Rewe ceremonial mapuche donde se realizan rogativas comunitarias. Espacio sagrado con significado espiritual.', ARRAY['historia','ecologia','matematica'], 'cultural_mapuche', ARRAY['perdida_tradiciones','urbanizacion'], ST_SetSRID(ST_MakePoint(-72.019, -38.935), 4326)),
('Huerto Medicinal Mapuche Cunco', 'cultural', 'cultural_mapuche', 'Cunco', 'Huerto comunitario con plantas medicinales mapuche: matico, boldo, bailahuén, canelo. Mantenido por lawentuchefe local.', ARRAY['biologia','quimica','historia'], 'cultural_mapuche', ARRAY['perdida_conocimiento','herbicidas'], ST_SetSRID(ST_MakePoint(-72.030, -38.932), 4326)),
('Afloramiento Volcánico Cunco', 'geological', 'volcanico', 'Cunco', 'Formación de rocas volcánicas expuestas por erosión del río. Evidencia de actividad volcánica antigua.', ARRAY['geologia','fisica','quimica'], 'natural', ARRAY['extraccion_aridos'], ST_SetSRID(ST_MakePoint(-72.022, -38.925), 4326)),
('Vega Los Notros', 'natural', 'humedal', 'Cunco', 'Pequeño humedal estacional con vegetación hidrófila. Sitio de alimentación de aves locales como el queltehue.', ARRAY['biologia','ecologia'], 'natural', ARRAY['drenaje_agricola','contaminacion'], ST_SetSRID(ST_MakePoint(-72.035, -38.927), 4326));
INSERT INTO points_of_interest (name, type, ecosystem_type, commune, description, stem_areas, heritage_type, threats, location) VALUES
('Estero Las Quilas', 'hydrological', 'fluvial', 'Cunco', 'Estero rodeado de quilantales densos. Refugio de chucao y huet-huet. Agua cristalina de vertiente.', ARRAY['biologia','quimica','ecologia'], 'natural', ARRAY['deforestacion','contaminacion_agricola'], ST_SetSRID(ST_MakePoint(-71.975, -38.876), 4326)),
('Renoval de Roble Los Laureles', 'natural', 'bosque_nativo', 'Cunco', 'Renoval de roble pellín en recuperación natural. Ejemplo de sucesión ecológica post-tala.', ARRAY['biologia','ecologia'], 'natural', ARRAY['tala_ilegal','incendios'], ST_SetSRID(ST_MakePoint(-71.984, -38.885), 4326)),
('Cancha de Palín Los Laureles', 'cultural', 'cultural_mapuche', 'Cunco', 'Campo tradicional donde se juega palín (chueca mapuche). Espacio de encuentro comunitario.', ARRAY['historia','matematica','fisica'], 'cultural_mapuche', ARRAY['perdida_tradiciones','cambio_uso_suelo'], ST_SetSRID(ST_MakePoint(-71.977, -38.883), 4326)),
('Vertiente El Canelo', 'hydrological', 'vertiente', 'Cunco', 'Vertiente natural rodeada de canelos (foye), árbol sagrado mapuche. Agua de consumo comunitario.', ARRAY['quimica','biologia','ecologia'], 'natural_cultural', ARRAY['sequia','contaminacion'], ST_SetSRID(ST_MakePoint(-71.983, -38.875), 4326)),
('Praderas Nativas Los Laureles', 'natural', 'pradera', 'Cunco', 'Pradera con gramíneas nativas y flores silvestres. Hábitat de insectos polinizadores y aves de pastizal.', ARRAY['biologia','ecologia','matematica'], 'natural', ARRAY['monocultivo','herbicidas'], ST_SetSRID(ST_MakePoint(-71.985, -38.888), 4326)),
('Suelo Volcánico Los Laureles', 'geological', 'volcanico', 'Cunco', 'Perfil de suelo trumaos (ceniza volcánica) visible en corte de camino. Ideal para estudiar edafología.', ARRAY['geologia','quimica','biologia'], 'natural', ARRAY['erosion'], ST_SetSRID(ST_MakePoint(-71.978, -38.878), 4326));
INSERT INTO points_of_interest (name, type, ecosystem_type, commune, description, stem_areas, heritage_type, threats, location) VALUES
('Estero Mahuidanche', 'hydrological', 'fluvial', 'Cunco', 'Estero de aguas limpias que baja de la cordillera. Presencia de fauna bentónica indicadora de calidad.', ARRAY['biologia','quimica','ecologia'], 'natural', ARRAY['contaminacion_agricola'], ST_SetSRID(ST_MakePoint(-72.095, -38.966), 4326)),
('Bosque de Coigüe Mahuidanche', 'natural', 'bosque_nativo', 'Cunco', 'Bosque adulto de coigüe con sotobosque de helechos y nalcas. Presencia de monito del monte.', ARRAY['biologia','ecologia'], 'natural', ARRAY['tala','plantaciones_forestales'], ST_SetSRID(ST_MakePoint(-72.105, -38.975), 4326)),
('Fogón Mapuche Mahuidanche', 'cultural', 'cultural_mapuche', 'Cunco', 'Ruka con fogón central donde se reúne la comunidad mapuche. Transmisión oral de conocimiento.', ARRAY['historia','tecnologia','quimica'], 'cultural_mapuche', ARRAY['perdida_lengua','migracion_juvenil'], ST_SetSRID(ST_MakePoint(-72.097, -38.972), 4326)),
('Quebrada Los Helechos', 'geological', 'montano', 'Cunco', 'Quebrada profunda con paredes de roca volcánica y abundantes helechos. Microclima húmedo.', ARRAY['geologia','biologia','fisica'], 'natural', ARRAY['erosion','basura'], ST_SetSRID(ST_MakePoint(-72.103, -38.968), 4326)),
('Vertiente La Nalca', 'hydrological', 'vertiente', 'Cunco', 'Surgencia de agua subterránea rodeada de nalcas gigantes. Punto de agua para fauna silvestre.', ARRAY['quimica','biologia','geologia'], 'natural', ARRAY['sequia','cambio_climatico'], ST_SetSRID(ST_MakePoint(-72.098, -38.964), 4326)),
('Matorral Nativo Mahuidanche', 'natural', 'matorral', 'Cunco', 'Matorral de maqui, arrayán y chilco. Fuente de frutos comestibles y tinturas naturales.', ARRAY['biologia','quimica'], 'natural', ARRAY['roce_agricola'], ST_SetSRID(ST_MakePoint(-72.107, -38.973), 4326));
INSERT INTO points_of_interest (name, type, ecosystem_type, commune, description, stem_areas, heritage_type, threats, location) VALUES
('Estero El Maitén', 'hydrological', 'fluvial', 'Curacautín', 'Estero urbano con riberas de maitenes. Indicador ambiental de la salud del ecosistema local.', ARRAY['biologia','quimica','ecologia'], 'natural', ARRAY['contaminacion_domestica','canalizacion'], ST_SetSRID(ST_MakePoint(-71.885, -38.430), 4326)),
('Parque Urbano Curacautín', 'natural', 'bosque_nativo', 'Curacautín', 'Área verde con árboles nativos maduros: robles, coigües y avellanos. Nidificación de aves urbanas.', ARRAY['biologia','ecologia','matematica'], 'natural', ARRAY['podas_excesivas','contaminacion'], ST_SetSRID(ST_MakePoint(-71.892, -38.436), 4326)),
('Piedra de Moler Mapuche', 'cultural', 'cultural_mapuche', 'Curacautín', 'Sitio con piedras de moler (kudi) ancestrales mapuche. Evidencia de asentamiento prehispánico.', ARRAY['historia','geologia','matematica'], 'cultural_mapuche', ARRAY['vandalismo','desconocimiento'], ST_SetSRID(ST_MakePoint(-71.886, -38.437), 4326)),
('Suelo Trumaos Curacautín', 'geological', 'volcanico', 'Curacautín', 'Corte de terreno que expone capas de ceniza volcánica (trumaos). Registro geológico de erupciones.', ARRAY['geologia','quimica','fisica'], 'natural', ARRAY['erosion','extraccion'], ST_SetSRID(ST_MakePoint(-71.893, -38.431), 4326)),
('Huerta Escolar Orgánica', 'natural', 'agroecologico', 'Curacautín', 'Huerta comunitaria con cultivos orgánicos adaptados al clima local. Práctica de agroecología.', ARRAY['biologia','quimica','tecnologia'], 'natural', ARRAY['plagas','sequia'], ST_SetSRID(ST_MakePoint(-71.890, -38.429), 4326)),
('Ribera del Cautín Curacautín', 'hydrological', 'fluvial', 'Curacautín', 'Tramo del río Cautín con playa de arena volcánica negra. Zona de recreación y observación de aves.', ARRAY['biologia','geologia','ecologia'], 'natural', ARRAY['extraccion_aridos','contaminacion'], ST_SetSRID(ST_MakePoint(-71.884, -38.435), 4326));
INSERT INTO points_of_interest (name, type, ecosystem_type, commune, description, stem_areas, heritage_type, threats, location) VALUES
('Bosque de Lenga Captren', 'natural', 'bosque_nativo', 'Curacautín', 'Bosque de lenga en zona de transición altitudinal. Colores otoñales espectaculares.', ARRAY['biologia','ecologia','fisica'], 'natural', ARRAY['tala','cambio_climatico'], ST_SetSRID(ST_MakePoint(-71.715, -38.547), 4326)),
('Estero Captren', 'hydrological', 'fluvial', 'Curacautín', 'Estero de montaña con aguas frías y transparentes. Hábitat de insectos acuáticos nativos.', ARRAY['biologia','quimica','ecologia'], 'natural', ARRAY['extraccion_agua'], ST_SetSRID(ST_MakePoint(-71.725, -38.553), 4326)),
('Lahar Antiguo Captren', 'geological', 'volcanico', 'Curacautín', 'Depósito de lahar (flujo volcánico) del volcán Llaima visible en corte de río. Registro geológico.', ARRAY['geologia','fisica','quimica'], 'natural', ARRAY['erosion'], ST_SetSRID(ST_MakePoint(-71.718, -38.545), 4326)),
('Nguillatuhue Captren', 'cultural', 'cultural_mapuche', 'Curacautín', 'Campo ceremonial de comunidad pehuenche local. Ceremonias vinculadas al ciclo del piñón.', ARRAY['historia','ecologia','matematica'], 'cultural_mapuche', ARRAY['perdida_tradiciones'], ST_SetSRID(ST_MakePoint(-71.723, -38.555), 4326)),
('Pradera Altoandina Captren', 'natural', 'pradera_altitud', 'Curacautín', 'Pradera de altura con flora nativa adaptada al frío. Floración primaveral de violetas y orquídeas.', ARRAY['biologia','ecologia'], 'natural', ARRAY['sobrepastoreo','cambio_climatico'], ST_SetSRID(ST_MakePoint(-71.717, -38.552), 4326)),
('Vertiente Termal Captren', 'hydrological', 'termal', 'Curacautín', 'Surgencia de agua tibia de origen geotérmico. Mineralización especial por actividad volcánica.', ARRAY['geologia','quimica','fisica'], 'natural', ARRAY['sobreexplotacion'], ST_SetSRID(ST_MakePoint(-71.722, -38.548), 4326));
INSERT INTO points_of_interest (name, type, ecosystem_type, commune, description, stem_areas, heritage_type, threats, location) VALUES
('Bosque de Araucaria Llanquén', 'natural', 'bosque_araucaria', 'Curacautín', 'Bosque de araucarias centenarias. Recolección tradicional de piñones por comunidad pehuenche.', ARRAY['biologia','ecologia','matematica'], 'natural_cultural', ARRAY['cambio_climatico','recoleccion_excesiva'], ST_SetSRID(ST_MakePoint(-71.645, -38.497), 4326)),
('Estero Llanquén', 'hydrological', 'fluvial', 'Curacautín', 'Estero de montaña con pozones naturales. Agua de deshielo con fauna acuática nativa.', ARRAY['biologia','quimica'], 'natural', ARRAY['sequia_estival'], ST_SetSRID(ST_MakePoint(-71.655, -38.503), 4326)),
('Morena Glaciar Llanquén', 'geological', 'glaciar', 'Curacautín', 'Depósito morrénico de la última glaciación. Rocas transportadas por glaciar hace miles de años.', ARRAY['geologia','fisica','matematica'], 'natural', ARRAY['erosion'], ST_SetSRID(ST_MakePoint(-71.648, -38.495), 4326)),
('Piñonera Comunitaria Llanquén', 'cultural', 'cultural_mapuche', 'Curacautín', 'Zona de recolección ancestral de piñones (ngüilliu). Práctica económica y cultural pehuenche.', ARRAY['biologia','historia','matematica'], 'cultural_mapuche', ARRAY['cambio_climatico','restricciones_legales'], ST_SetSRID(ST_MakePoint(-71.653, -38.505), 4326)),
('Turbera Llanquén', 'natural', 'humedal', 'Curacautín', 'Turbera de Sphagnum en zona alta. Almacén natural de carbono y agua. Ecosistema frágil.', ARRAY['biologia','quimica','ecologia'], 'natural', ARRAY['drenaje','cambio_climatico'], ST_SetSRID(ST_MakePoint(-71.647, -38.502), 4326)),
('Cueva Volcánica Llanquén', 'geological', 'volcanico', 'Curacautín', 'Tubo de lava formado por erupciones antiguas. Formaciones de estalactitas de lava.', ARRAY['geologia','fisica'], 'natural', ARRAY['vandalismo','turismo_no_regulado'], ST_SetSRID(ST_MakePoint(-71.652, -38.498), 4326));
INSERT INTO points_of_interest (name, type, ecosystem_type, commune, description, stem_areas, heritage_type, threats, location) VALUES
('Estero Manzanar', 'hydrological', 'fluvial', 'Curacautín', 'Estero con ribera de manzanos silvestres naturalizados. Mezcla de flora nativa e introducida.', ARRAY['biologia','ecologia','quimica'], 'natural', ARRAY['contaminacion_agricola'], ST_SetSRID(ST_MakePoint(-71.796, -38.487), 4326)),
