('Cementerio Mapuche Manzanar', 'cultural', 'cultural_mapuche', 'Curacautín', 'Eltun (cementerio) mapuche ancestral con chemamüll (estatuas de madera). Sitio patrimonial.', ARRAY['historia','matematica','tecnologia'], 'cultural_mapuche', ARRAY['deterioro','olvido'], ST_SetSRID(ST_MakePoint(-71.803, -38.488), 4326)),
('Loma Volcánica Manzanar', 'geological', 'volcanico', 'Curacautín', 'Loma formada por acumulación de material piroclástico. Vista panorámica del valle y volcanes.', ARRAY['geologia','fisica','matematica'], 'natural', ARRAY['erosion','extraccion_aridos'], ST_SetSRID(ST_MakePoint(-71.798, -38.485), 4326)),
('Huerto de Plantas Tintóreas', 'cultural', 'cultural_mapuche', 'Curacautín', 'Jardín con plantas usadas para teñir lana: maqui, michay, barba de viejo. Técnica textil mapuche.', ARRAY['quimica','biologia','historia'], 'cultural_mapuche', ARRAY['perdida_conocimiento'], ST_SetSRID(ST_MakePoint(-71.802, -38.492), 4326)),
('Vega Manzanar', 'natural', 'humedal', 'Curacautín', 'Pradera húmeda con juncos y totoras. Hábitat de ranas y sapos nativos.', ARRAY['biologia','ecologia'], 'natural', ARRAY['drenaje_agricola','sobrepastoreo'], ST_SetSRID(ST_MakePoint(-71.797, -38.494), 4326));
INSERT INTO points_of_interest (name, type, ecosystem_type, commune, description, stem_areas, heritage_type, threats, location) VALUES
('Estero Lonquimay', 'hydrological', 'fluvial', 'Lonquimay', 'Estero que atraviesa el pueblo de Lonquimay. Aguas de deshielo con fauna bentónica.', ARRAY['biologia','quimica','ecologia'], 'natural', ARRAY['contaminacion_domestica'], ST_SetSRID(ST_MakePoint(-71.239, -38.432), 4326)),
