('Rewe Pehuenche Lonquimay', 'cultural', 'cultural_mapuche', 'Lonquimay', 'Rewe ceremonial de la comunidad pehuenche de Lonquimay. Centro de vida espiritual comunitaria.', ARRAY['historia','ecologia','matematica'], 'cultural_mapuche', ARRAY['perdida_tradiciones'], ST_SetSRID(ST_MakePoint(-71.245, -38.430), 4326)),
('Cono Volcánico Navidad', 'geological', 'volcanico', 'Lonquimay', 'Cono volcánico formado en la erupción de 1988-89. Ejemplo vivo de vulcanismo reciente.', ARRAY['geologia','fisica','quimica'], 'natural', ARRAY['erosion'], ST_SetSRID(ST_MakePoint(-71.250, -38.440), 4326)),
('Vega del Biobío Naciente', 'natural', 'humedal', 'Lonquimay', 'Zona húmeda cercana al nacimiento del río Biobío. Ecosistema de humedal de altura.', ARRAY['biologia','ecologia','quimica'], 'natural', ARRAY['sobrepastoreo','sequia'], ST_SetSRID(ST_MakePoint(-71.238, -38.437), 4326)),
('Secadero de Piñones Pehuenche', 'cultural', 'cultural_mapuche', 'Lonquimay', 'Estructura tradicional para secar y almacenar piñones. Tecnología alimentaria ancestral.', ARRAY['tecnologia','historia','quimica'], 'cultural_mapuche', ARRAY['desuso','deterioro'], ST_SetSRID(ST_MakePoint(-71.244, -38.433), 4326));
INSERT INTO points_of_interest (name, type, ecosystem_type, commune, description, stem_areas, heritage_type, threats, location) VALUES
('Estero Cruzaco', 'hydrological', 'fluvial', 'Lonquimay', 'Estero de aguas limpias con ribera de ñires. Hábitat de truchas nativas.', ARRAY['biologia','quimica','ecologia'], 'natural', ARRAY['extraccion_agua'], ST_SetSRID(ST_MakePoint(-71.147, -38.517), 4326)),
