('Escorial Volcánico Cruzaco', 'geological', 'volcanico', 'Lonquimay', 'Campo de lava solidificada con líquenes colonizadores. Sucesión primaria en proceso.', ARRAY['geologia','biologia','ecologia'], 'natural', ARRAY['extraccion_roca'], ST_SetSRID(ST_MakePoint(-71.148, -38.523), 4326)),
('Mallín Cruzaco', 'natural', 'humedal', 'Lonquimay', 'Mallín (vega de altura) con pastos nativos y juncos. Fuente de agua para ganado.', ARRAY['biologia','ecologia'], 'natural', ARRAY['sobrepastoreo','drenaje'], ST_SetSRID(ST_MakePoint(-71.145, -38.515), 4326)),
('Mirador Cerro Cruzaco', 'geological', 'montano', 'Lonquimay', 'Punto alto con vista panorámica a volcanes Lonquimay, Llaima y Sierra Nevada. Rocas metamórficas.', ARRAY['geologia','fisica','matematica'], 'natural', ARRAY['erosion'], ST_SetSRID(ST_MakePoint(-71.152, -38.522), 4326));
INSERT INTO points_of_interest (name, type, ecosystem_type, commune, description, stem_areas, heritage_type, threats, location) VALUES
('Lago Icalma Orilla Norte', 'hydrological', 'lacustre', 'Lonquimay', 'Orilla accesible del lago Icalma. Aguas oligotróficas rodeadas de araucarias. Nacimiento del río Biobío.', ARRAY['biologia','quimica','ecologia'], 'natural', ARRAY['turismo_no_regulado','contaminacion'], ST_SetSRID(ST_MakePoint(-71.275, -38.775), 4326)),
