('Ruka Pehuenche Icalma', 'cultural', 'cultural_mapuche', 'Lonquimay', 'Ruka tradicional pehuenche de la comunidad de Icalma. Construcción con materiales del bosque.', ARRAY['tecnologia','historia','matematica'], 'cultural_mapuche', ARRAY['perdida_tecnicas','migracion'], ST_SetSRID(ST_MakePoint(-71.278, -38.782), 4326)),
('Depósito Glaciar Icalma', 'geological', 'glaciar', 'Lonquimay', 'Morrena lateral de glaciación pleistocénica. Bloques erráticos transportados por el hielo.', ARRAY['geologia','fisica','matematica'], 'natural', ARRAY['erosion'], ST_SetSRID(ST_MakePoint(-71.283, -38.776), 4326)),
('Humedal Desembocadura Icalma', 'natural', 'humedal', 'Lonquimay', 'Zona húmeda donde el estero desemboca en el lago. Sitio de alimentación de taguas y patos.', ARRAY['biologia','ecologia'], 'natural', ARRAY['contaminacion','turismo'], ST_SetSRID(ST_MakePoint(-71.276, -38.778), 4326)),
('Sendero Interpretativo Pewenche', 'cultural', 'cultural_mapuche', 'Lonquimay', 'Sendero con señalética en mapuzugun sobre plantas medicinales y alimenticias del bosque pewenche.', ARRAY['biologia','historia','ecologia'], 'cultural_mapuche', ARRAY['deterioro_señaletica'], ST_SetSRID(ST_MakePoint(-71.282, -38.785), 4326));
INSERT INTO points_of_interest (name, type, ecosystem_type, commune, description, stem_areas, heritage_type, threats, location) VALUES
('Estero Pehuenco', 'hydrological', 'fluvial', 'Lonquimay', 'Estero de montaña con cascadas pequeñas. Aguas ricas en minerales volcánicos.', ARRAY['quimica','biologia','geologia'], 'natural', ARRAY['extraccion_agua'], ST_SetSRID(ST_MakePoint(-71.307, -38.477), 4326)),
('Pehuenera Milenaria Pehuenco', 'natural', 'bosque_araucaria', 'Lonquimay', 'Grupo de araucarias de más de 1000 años. Monumento natural de la comunidad pehuenche.', ARRAY['biologia','ecologia','matematica'], 'natural_cultural', ARRAY['cambio_climatico','incendios'], ST_SetSRID(ST_MakePoint(-71.315, -38.484), 4326)),
('Fogón Comunitario Pehuenco', 'cultural', 'cultural_mapuche', 'Lonquimay', 'Espacio de reunión comunitaria pehuenche alrededor del fuego. Tradición oral y toma de decisiones.', ARRAY['historia','tecnologia'], 'cultural_mapuche', ARRAY['perdida_tradiciones'], ST_SetSRID(ST_MakePoint(-71.312, -38.478), 4326)),
('Colada de Lava Pehuenco', 'geological', 'volcanico', 'Lonquimay', 'Flujo de lava antigua del volcán Lonquimay. Superficie rugosa con vegetación pionera.', ARRAY['geologia','biologia','ecologia'], 'natural', ARRAY['erosion'], ST_SetSRID(ST_MakePoint(-71.308, -38.483), 4326)),
('Mallín Pehuenco', 'natural', 'humedal', 'Lonquimay', 'Mallín de altura con flora adaptada a heladas. Importante reserva hídrica estacional.', ARRAY['biologia','ecologia','quimica'], 'natural', ARRAY['sobrepastoreo'], ST_SetSRID(ST_MakePoint(-71.305, -38.476), 4326)),
