INSERT INTO points_of_interest (name, type, ecosystem_type, commune, description, stem_areas, heritage_type, threats, location) VALUES
('Río Biobío Naciente Troyo', 'hydrological', 'fluvial', 'Lonquimay', 'Tramo del río Biobío joven, aguas turquesa de deshielo. Uno de los ríos más importantes de Chile.', ARRAY['biologia','quimica','ecologia'], 'natural', ARRAY['represas','contaminacion'], ST_SetSRID(ST_MakePoint(-71.185, -38.387), 4326)),
